{
  "id": "openclaw:core:exec",
  "source": "openclaw",
  "sourceName": "core",
  "name": "exec",
  "label": "exec",
  "description": "Run shell now; background continuation supported. Completed calls return command output directly. Use process only when exec reports running with a sessionId; output text alone is not a process handle. Long run: automatic completion wake when enabled and output/failure occurs; otherwise process confirms completion. Omit host to use the session's configured host. No sleep loops for reminders/follow-ups; use automations. TTY CLI/UI/coding agent: pty=true. Quote arguments containing shell metacharacters, including URL query strings with `?` or `&`.",
  "input": "{ command: string; ask?: string; awaitResults?: boolean; background?: boolean; elevated?: boolean; env?: { ... }; host?: \"auto\" | \"gateway\"; node?: string; pty?: boolean; timeoutSeconds?: number; title?: string; workdir?: string; yieldMs?: number }",
  "parameters": {
    "type": "object",
    "required": [
      "command"
    ],
    "properties": {
      "title": {
        "type": "string",
        "maxLength": 120,
        "description": "Every call: short purpose; never claim success. No secrets."
      },
      "command": {
        "type": "string",
        "description": "Shell command."
      },
      "workdir": {
        "type": "string",
        "description": "Omit/empty string: default; whitespace-only invalid."
      },
      "env": {
        "type": "object",
        "patternProperties": {
          "^.*$": {
            "type": "string"
          }
        },
        "description": "Literal overrides; no expansion. Omit to inherit."
      },
      "yieldMs": {
        "type": "number",
        "description": "Milliseconds before returning an ordinary-command handle; default 10000."
      },
      "awaitResults": {
        "type": "boolean",
        "description": "Result required to finish the task; wait for terminal collection. Not for detached servers."
      },
      "background": {
        "type": "boolean",
        "description": "Start an independent service now; survives request Stop. Use yieldMs for ordinary work. timeoutSeconds applies."
      },
      "timeoutSeconds": {
        "type": "number",
        "description": "Process lifetime in seconds; 0 disables."
      },
      "pty": {
        "type": "boolean",
        "description": "PTY for TTY-required CLIs/coding agents."
      },
      "elevated": {
        "type": "boolean",
        "description": "Host elevation if allowed."
      },
      "host": {
        "enum": [
          "auto",
          "gateway"
        ],
        "type": "string",
        "description": "Omit/auto: inherit configured host (gateway)."
      },
      "ask": {
        "type": "string",
        "description": "Requests stricter approvals under tools.exec.mode and host policy; channel-origin calls cannot override host ask=off."
      },
      "node": {
        "type": "string",
        "description": "Node id/name for host=node."
      }
    }
  }
}

