{
  "id": "openclaw:core:secrets",
  "source": "openclaw",
  "sourceName": "core",
  "name": "secrets",
  "label": "Secrets",
  "description": "Protected credentials: `list` metadata first; `request` missing task-needed name + reason via human masked entry; `delete` removes an entry. Request waits for human; value goes straight to shared store, never model/chat. Use the returned store SecretRef for supported config fields. Gateway HTTPS egress only: enabled proxy + exact allowedHosts required; no hosts blocks egress, not config refs. No plaintext fallback. Protected entries cannot supply SSH/sudo passwords or subprocess stdin; `${secret:NAME}` is not shell substitution. Check the supported consumer before requesting a credential. Gateway-host commands: use auto-injected opaque env sentinel under stored name. No secret templates; never override/print that variable. Native shell/sandbox/node: no protected injection. First command snapshots store for run; late saves need next turn. Operator-set env entries are readable and managed separately from this protected store. no_answer means no credential was supplied.",
  "input": "{ action: \"request\" | \"list\" | \"delete\"; allowedHosts?: Array<string>; kind?: \"secret\"; name?: string; reason?: string; timeoutSeconds?: number /* integer */ }",
  "parameters": {
    "type": "object",
    "required": [
      "action"
    ],
    "properties": {
      "action": {
        "enum": [
          "request",
          "list",
          "delete"
        ],
        "type": "string",
        "description": "`request` a value from the human, `list` entry metadata, or `delete` an entry."
      },
      "name": {
        "type": "string",
        "maxLength": 128,
        "pattern": "^[A-Z][A-Z0-9_]{0,127}$",
        "description": "Entry name in uppercase environment-variable form, also its SecretRef id (STRIPE_API_KEY). Required for request and delete."
      },
      "kind": {
        "enum": [
          "secret"
        ],
        "type": "string",
        "description": "Only `secret` may be requested; requested values are never readable back."
      },
      "allowedHosts": {
        "type": "array",
        "items": {
          "type": "string",
          "minLength": 1,
          "maxLength": 253
        },
        "maxItems": 128,
        "uniqueItems": true,
        "description": "Exact hostnames allowed to receive a secret, without scheme or port (api.stripe.com). Leaving this empty prevents egress substitution; config SecretRefs remain usable."
      },
      "reason": {
        "type": "string",
        "maxLength": 200,
        "description": "One line shown to the human explaining why the credential is needed."
      },
      "timeoutSeconds": {
        "type": "integer",
        "description": "Maximum human wait in seconds on request; default 900, clamped 30-3600. Earlier run cancellation or overall run timeout still applies."
      }
    },
    "additionalProperties": false
  }
}

